costs_data = cells('W0::Leaf costs', 'E30:F32')

costs = {row[0]: row[1] for row in costs_data}
rules = {}
for row in rules_data:
    parent, comp, mult = row[0], row[1], row[2]
    rules.setdefault(parent, []).append((comp, mult))

def get_cost(part):
    if part in costs:
        return costs[part]
    total = 0
    if part in rules:
        for comp, mult in rules[part]:
            total += mult * get_cost(comp)
    return total

crate_cost = get_cost('Crate')
beacon_cost = get_cost('Beacon')
result = round(crate_cost - beacon_cost, 2)

